def adopt_existing_departments(apps, schema_editor):
    """
    Students used to hold a free-text department. Make each distinct name
    (ignoring case) a real Department and tidy students to its spelling.
    """
    Department = apps.get_model('academics', 'Department')
    Student = apps.get_model('students', 'Student')
    canonical = {}
    for name in (
        Student.objects.exclude(department='')
        .order_by('id')
        .values_list('department', flat=True)
        .distinct()
    ):
        name = ' '.join(name.split())
        if name and name.lower() not in canonical:
            canonical[name.lower()] = Department.objects.create(name=name).name
    for student in Student.objects.exclude(department=''):
        wanted = canonical.get(' '.join(student.department.split()).lower())
        if wanted and wanted != student.department:
            student.department = wanted
            student.save(update_fields=['department'])


